import os,errno;f=open('bounded.bin','wb',buffering=0)
try:
 f.write(b'x'*(9*1024**2))
 f.write(b'x')
except OSError as e:
 assert e.errno==errno.EFBIG
 assert os.stat('bounded.bin').st_size==8*1024**2
 print('EXPECTED_EFBIG_AT_8MIB',flush=True)
else:raise AssertionError('No native file cap')
